Update _check_list_display_item to follow the logic below. Do not use hasattr(model, item) as a gate before trying get_field, because hasattr(model, item) being false should not stop Django from resolving the field through get_field. Only return E108 if both lookups fail. If either lookup succeeds, check whether the result is a ManyToManyField. Whether field is None should not drive the flow here; the exception handling should decide that instead of overloading None to mean different things.

def _check_list_display_item(self, obj, item, label):
	if callable(item):
		return []
	elif hasattr(obj, item):
		return []
	else:
		try:
			field = obj.model._meta.get_field(item)
		except FieldDoesNotExist:
			try:
				field = getattr(obj.model, item)
			except AttributeError:
				return [
					checks.Error(
						"The value of '%s' refers to '%s', which is not a callable, "
						"an attribute of '%s', or an attribute or method on '%s.%s'." % (
							label, item, obj.__class__.__name__,
							obj.model._meta.app_label, obj.model._meta.object_name,
						),
						obj=obj.__class__,
						id='admin.E108',
					)
				]
		if isinstance(field, models.ManyToManyField):
			return [
				checks.Error(
					"The value of '%s' must not be a ManyToManyField." % label,
					obj=obj.__class__,
					id='admin.E109',
				)
			]
		return []

